/** A packed table as a map, built on first use. */
function blockMap(packed: string): () => Map<string, string> {
  let map: Map<string, string> | null = null;
  return () => {
    if (map === null) {
      map = new Map();
      for (const line of packed.split('\n')) {
        const at = line.indexOf(' ');
        if (at > 0) map.set(line.slice(0, at), line.slice(at + 1));
      }
    }
    return map;
  };
}

const oui28 = blockMap(OUI28_BLOCKS);
const oui36 = blockMap(OUI36_BLOCKS);

/**
 * The vendor name and the bits of the address it does not cover, formatted as
 * the reference analyzer does: "Name_cc:dd:ee" for a 24-bit block,
 * "Name_d:ee:ff" for 28 bits and "Name_e:ff" for 36, where the single digit is
 * the low nibble the block leaves free (Wireshark's `eth_resolved_name_fill`).
 * Null when no block claims it.
 */
function vendorName(lower: string): string | null {
  const hex = lower.replace(/:/g, '').toUpperCase();
  const parts = octets(lower);
  const in36 = oui36().get(hex.slice(0, 9));
  if (in36) return `${in36}_${hex[9].toLowerCase()}:${parts[5]}`;
  const in28 = oui28().get(hex.slice(0, 7));
  if (in28) return `${in28}_${hex[7].toLowerCase()}:${parts[4]}:${parts[5]}`;
  const in24 = OUI_VENDOR_MAP[lower.slice(0, 8).toUpperCase()];
  return in24 ? `${in24}_${parts.slice(3).join(':')}` : null;
}

/**
 * Splits a lowercase "aa:bb:cc:dd:ee:ff" into its octet strings.
 */
function octets(mac: string): string[] {
  return mac.split(':');
}

/**
 * Resolves a MAC to the short display name the reference analyzer shows in the packet-list
 * address columns: "SagemcomBroa_aa:bb:cc", "Broadcast",
 * "IPv6mcast_ff:8c:e5:bf". Falls back to the raw MAC when the OUI is unknown,
 * which is also what the reference analyzer does.
 *
 * Deliberately distinct from resolveMacVendor() below: the columns want the
 * bare name, while the detail tree wants the name *and* the literal address.
 */
/**
 * Resolved names, by MAC.
 *
 * This is a pure function of its argument called twice for every frame - once
 * for each end - over a domain that is, on any real segment, a couple of dozen
 * addresses. A CPU profile put it and its `octets` helper at ~4.8% of a
 * dissection run, all of it recomputing the same few answers.
 *
 * Capped rather than unbounded: a capture that sees an unusual number of
 * distinct MACs (a scan, a busy trunk port) should not grow this without
 * limit. At the cap it stops admitting new entries rather than evicting, since
 * the entries already there are the ones being asked for repeatedly.
 */
const macNameCache = new Map<string, string>();
const MAC_NAME_CACHE_MAX = 4096;
/**
 * The display string, beside the name `resolveMacName` caches: an Ethernet
 * frame asks for it four times (each address, and each address's `eth.addr`
 * row), and rebuilt it - two lowercasings and a template - every time.
 */
const macVendorCache = new Map<string, string>();

export function resolveMacName(mac: string): string {
  const cached = macNameCache.get(mac);
  if (cached !== undefined) return cached;
  const name = computeMacName(mac);
  if (macNameCache.size < MAC_NAME_CACHE_MAX) macNameCache.set(mac, name);
  return name;
}

function computeMacName(mac: string): string {
  const lower = mac.toLowerCase();

  const reserved = RESERVED_MAC_NAMES[lower];
  if (reserved) return reserved;

  for (const { prefix, label, keepBytes } of MULTICAST_PREFIXES) {
    if (lower.startsWith(`${prefix}:`)) {
      return `${label}_${octets(lower).slice(6 - keepBytes).join(':')}`;
    }
  }

  return vendorName(lower) ?? lower;
}

/**
 * Formats a MAC address with its resolved name for the protocol detail tree,
 * Reference-analyzer style ("SagemcomBroa_aa:bb:cc (44:15:24:aa:bb:cc)"), falling back
 * to the raw MAC unchanged when nothing resolves.
 */
export function resolveMacVendor(mac: string): string {
  const cached = macVendorCache.get(mac);
  if (cached !== undefined) return cached;
  const name = resolveMacName(mac);
  const shown = name === mac.toLowerCase() ? mac : `${name} (${mac.toLowerCase()})`;
  if (macVendorCache.size < MAC_NAME_CACHE_MAX) macVendorCache.set(mac, shown);
  return shown;
}
